//! Whose elevation data each region's terrain is made from. Mapterhorn builds
//! its tiles from national elevation models where they are open and from
//! Copernicus GLO-30 elsewhere; each has its own producer and licence, and
//! most licences ask for a credit.
//!
//! The table is generated by `offline-maps-dev terrain-sources` from
//! Mapterhorn's coverage index, which lists the sources of every zoom 12 tile.
//! A region's sources are those of the tiles touching its outer box, which
//! holds the box its terrain is downloaded for, so a neighbour's source may be
//! listed for a region whose terrain has none of it.
#[path = "terrain_sources_data.rs"]
mod data;

pub use data::{COVERAGE_DATE, SOURCES};

/// Where Mapterhorn lists every source with its licence.
pub const SOURCES_PAGE: &str = "mapterhorn.com/attribution";
/// Mapterhorn's coverage index: a PMTiles archive whose tiles are JSON
/// objects, source ID to that source's details.
pub const COVERAGE_INDEX_URL: &str = "https://download.mapterhorn.com/coverage-index.pmtiles";

/// One producer's elevation data under one licence. Mapterhorn's parts of a
/// dataset (the USGS 1 m model comes in 34) are one entry here.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TerrainSource {
    /// Short name for the credit line on the map ("USGS").
    pub short: &'static str,
    /// The producer as its licence wants it named.
    pub producer: &'static str,
    pub license: &'static str,
    pub website: &'static str,
    /// Words the licence wants shown on the map itself, or empty: the approval
    /// number under Japan's Survey Act.
    pub notice: &'static str,
}

/// The sources of a catalog region's terrain, finest resolution first. Empty
/// for a region the table does not have.
pub fn for_region(id: &str) -> Vec<&'static TerrainSource> {
    data::REGIONS
        .binary_search_by(|(region, _)| (*region).cmp(id))
        .map(|at| {
            data::REGIONS[at]
                .1
                .iter()
                .map(|i| &SOURCES[usize::from(*i)])
                .collect()
        })
        .unwrap_or_default()
}

/// The credit kept with a region's downloaded terrain.
pub fn attribution(id: &str) -> String {
    let sources = for_region(id);
    if sources.is_empty() {
        return format!("Terrain: Mapterhorn ({SOURCES_PAGE})");
    }
    let list: Vec<String> = sources
        .iter()
        .map(|s| format!("{} ({})", s.producer, s.license))
        .collect();
    format!(
        "Terrain: Mapterhorn ({SOURCES_PAGE}), from {}",
        list.join("; ")
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::regions;

    fn shorts(id: &str) -> Vec<&'static str> {
        for_region(id).iter().map(|s| s.short).collect()
    }

    #[test]
    fn every_region_has_sources() {
        for r in &regions::ALL {
            assert!(!for_region(r.id).is_empty(), "{}", r.id);
        }
        assert!(for_region("nowhere").is_empty());
        for pair in data::REGIONS.windows(2) {
            assert!(pair[0].0 < pair[1].0, "{} {}", pair[0].0, pair[1].0);
        }
        for s in &SOURCES {
            assert!(!s.short.is_empty() && !s.producer.is_empty() && !s.license.is_empty());
        }
        assert_eq!(COVERAGE_DATE.len(), 10);
    }

    #[test]
    fn sources_follow_the_region() {
        // The US: the national model, with Copernicus where it has gaps.
        let illinois = shorts("us-il");
        assert!(illinois.contains(&"USGS"), "{illinois:?}");
        assert!(!illinois.contains(&"GSI"));
        // Japan's survey data must be shown with its approval number.
        let japan: Vec<_> = regions::ALL
            .iter()
            .filter(|r| r.country == "Japan")
            .collect();
        assert!(!japan.is_empty());
        for r in japan {
            let gsi = for_region(r.id)
                .into_iter()
                .find(|s| s.short == "GSI")
                .unwrap_or_else(|| panic!("{}", r.id));
            assert!(gsi.notice.contains("承認"), "{}", gsi.notice);
            assert!(attribution(r.id).contains("国土地理院"));
        }
        // Only Copernicus covers Afghanistan.
        assert_eq!(shorts("af"), ["Copernicus"]);
        assert!(
            attribution("us-il")
                .starts_with("Terrain: Mapterhorn (mapterhorn.com/attribution), from ")
        );
        assert_eq!(
            attribution("nowhere"),
            "Terrain: Mapterhorn (mapterhorn.com/attribution)"
        );
    }
}
